script:
root = repo.list(".")
out = {"root": root}
out["cargo_toml"] = repo.read("Cargo.toml", missing_ok=True)
for d in ["src", "tests", "benches", "examples"]:
    if d in root:
        out[d] = repo.list(d)
# walk src recursively
def walk(path, depth):
    if depth > 3:
        return None
    listing = repo.list(path)
    res = {}
    for e in listing:
        if e.endswith("/"):
            res[e] = walk(path.rstrip("/") + "/" + e, depth + 1)
        else:
            res[e] = None
    return res
out["tree"] = walk(".", 0)
return out
